// Лента дропов: только 30 скинов от 5 000 ₽ (состав фиксирован)
const LIVE_POOL = (() => {
  const rnd = seededRandom("live-feed");
  const ids = Object.values(ITEMS)
    .filter(i => i.id.startsWith("skin_") && i.price >= 5000)
    .map(i => i.id);
  for (let k = ids.length - 1; k > 0; k--) {
    const j = Math.floor(rnd() * (k + 1));
    [ids[k], ids[j]] = [ids[j], ids[k]];
  }
  return ids.slice(0, 30);
})();

